  return [
    {
      name: 'open_client',
      description: 'Open a client with its own independent key/value map.',
      inputSchema: {
        type: 'object',
        properties: {
          client_id: { type: 'string' }
        },
        required: ['client_id'],
        additionalProperties: false
      }
    },
    {
      name: 'client_put',
      description: 'Write a key/value pair into a client\'s map.',
      inputSchema: {
        type: 'object',
        properties: {
          client_id: { type: 'string' },
          key: { type: 'string' },
          value: { type: 'string' }
